import { useState } from 'react';

function Counter() {
  const [count, setCount] = useState(0);

  return (
    <button onClick={() => setCount(prev => prev + 1)}>
      Count: {count}
    </button>
  );
}

import { useState, useEffect } from 'react';

function Timer() {
  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setSeconds(s => s + 1);
    }, 1000);

    // Cleanup runs when component unmounts or before rerun
    return () => clearInterval(interval);
  }, []); // Empty dependency array means runs once on mount

  return <p>Seconds: {seconds}</p>;
}

import { createContext, useContext } from 'react';

const ThemeContext = createContext('dark');

function Display() {
  const theme = useContext(ThemeContext);
  return <div className={`theme-&{theme}`}>Active Theme: {theme}</div>;
}

import { useRef } from 'react';

function TextInputWithFocusButton() {
  const inputEl = useRef<HTMLInputElement>(null);

  const onButtonClick = () => {
    // Access the native DOM input directly
    inputEl.current?.focus();
  };

  return (
    <>
      <input ref={inputEl} type="text" />
      <button onClick={onButtonClick}>Focus the input</button>
    </>
  );
}

import { useMemo } from 'react';

function ProductList({ items, filterQuery }) {
  // Caches computed array to avoid re-filtering on every unrelated render
  const filteredItems = useMemo(() => {
    return items.filter(item => item.includes(filterQuery));
  }, [items, filterQuery]);

  return <ul>{filteredItems.map(x => <li key={x}>{x}</li>)}</ul>;
}

import { useCallback } from 'react';

function Parent({ id }) {
  // Memoizes function reference to prevent Child re-renders
  const handleClick = useCallback(() => {
    console.log('Clicked item:', id);
  }, [id]);

  return <Child onClick={handleClick} />;
}

import { useReducer } from 'react';

const reducer = (state, action) => {
  switch (action.type) {
    case 'increment': return { count: state.count + 1 };
    case 'decrement': return { count: state.count - 1 };
    default: throw new Error();
  }
};

function Counter() {
  const [state, dispatch] = useReducer(reducer, { count: 0 });
  return (
    <>
      Count: {state.count}
      <button onClick={() => dispatch({ type: 'increment' })}>+</button>
      <button onClick={() => dispatch({ type: 'decrement' })}>-</button>
    </>
  );
}

import { useState, useLayoutEffect, useRef } from 'react';

function Tooltip() {
  const [height, setHeight] = useState(0);
  const divRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    // Runs synchronously AFTER DOM changes but BEFORE browser paint
    if (divRef.current) {
      setHeight(divRef.current.getBoundingClientRect().height);
    }
  }, []);

  return <div ref={divRef}>Height is {height}px</div>;
}

import { forwardRef, useImperativeHandle, useRef } from 'react';

const FancyInput = forwardRef((props, ref) => {
  const inputRef = useRef<HTMLInputElement>(null);

  useImperativeHandle(ref, () => ({
    focus: () => {
      inputRef.current?.focus();
    }
  }));

  return <input ref={inputRef} />;
});

import { useState, useTransition } from 'react';

function FilterList() {
  const [isPending, startTransition] = useTransition();
  const [filter, setFilter] = useState('');

  const updateFilter = (e) => {
    // Updates input immediately, but defers complex filtering rendering
    startTransition(() => {
      setFilter(e.target.value);
    });
  };

  return <input type="text" onChange={updateFilter} />;
}

import { useState, useDeferredValue } from 'react';

function Search({ query }) {
  // Defers update of this value when typing is in progress
  const deferredQuery = useDeferredValue(query);

  return <HeavyList query={deferredQuery} />;
}

import { useId } from 'react';

function PasswordField() {
  const passwordHintId = useId();

  return (
    <>
      <label htmlFor={passwordHintId}>Password: </label>
      <input id={passwordHintId} type="password" />
    </>
  );
}

import { use } from 'react';

function Post({ fetchPromise }) {
  // Resolves promise directly inside render without useEffect
  const data = use(fetchPromise);
  return <h2>{data.title}</h2>;
}

import { useActionState } from 'react';

async function updateName(prevState, formData) {
  const name = formData.get('name');
  return { success: true, name };
}

function ProfileForm() {
  const [state, formAction, isPending] = useActionState(updateName, null);

  return (
    <form action={formAction}>
      <input type="text" name="name" />
      <button disabled={isPending}>Submit</button>
    </form>
  );
}

import { useFormStatus } from 'react-dom';

function SubmitButton() {
  // Checks status of the parent form context
  const { pending } = useFormStatus();

  return (
    <button type="submit" disabled={pending}>
      {pending ? 'Submitting...' : 'Submit'}
    </button>
  );
}

import { useOptimistic } from 'react';

function MessageList({ messages }) {
  // Creates temporary optimistic state
  const [optimisticMessages, addOptimisticMessage] = useOptimistic(
    messages,
    (state, newMessage) => [...state, { text: newMessage, sending: true }]
  );

  return (
    <div>
      {optimisticMessages.map(m => <p key={m.text}>{m.text} {m.sending && '(sending...)'}</p>)}
    </div>
  );
}
